"""Common services (W2.12) - generated by archres_core.design.commons."""

import json
import math
import os
import pathlib

import FreeCAD as App
import Part

DESIGN = {
 "flights": [
  {
   "angleDeg": 36.8699,
   "baseZMm": 3200.0,
   "id": "1",
   "riseMm": 3000.0,
   "runMm": 4000.0,
   "thicknessMm": 150.0,
   "widthMm": 1000.0,
   "xMm": 500.0,
   "yMm": 6689.0
  }
 ],
 "landings": [
  {
   "depthMm": 1200.0,
   "id": "1",
   "thicknessMm": 150.0,
   "widthMm": 1000.0,
   "xMm": 500.0,
   "yMm": 6689.0,
   "zMm": 6200.0
  }
 ],
 "lifts": [
  {
   "baseZMm": 3200.0,
   "carMm": 1400.0,
   "heightMm": 2400.0,
   "id": "1",
   "shaftMm": 1800.0,
   "xMm": 10100.0,
   "yMm": 7289.0
  }
 ],
 "projectId": "7c9e6f10-2a3b-4c5d-9e8f-1a2b3c4d5e6f",
 "runs": [
  {
   "diameterMm": 25.0,
   "id": "1",
   "kind": "conduit",
   "lengthMm": 9000.0,
   "xMm": 500.0,
   "yMm": 6689.0,
   "zMm": 3500.0
  },
  {
   "diameterMm": 50.0,
   "id": "1",
   "kind": "waterPipe",
   "lengthMm": 1.0,
   "xMm": 500.0,
   "yMm": 6689.0,
   "zMm": 3450.0
  },
  {
   "diameterMm": 25.0,
   "id": "1",
   "kind": "gasPipe",
   "lengthMm": 1.0,
   "xMm": 500.0,
   "yMm": 6689.0,
   "zMm": 3450.0
  }
 ],
 "storeyIndex": 1
}


def _box(x_mm, y_mm, z_mm, size_x, size_y, size_z):
    return Part.makeBox(
        size_x,
        size_y,
        size_z,
        App.Vector(x_mm, y_mm, z_mm),
    )


def build():
    document = App.ActiveDocument
    if document is None:
        raise RuntimeError("no active document: the launcher always creates one")
    for flight in DESIGN["flights"]:
        length = math.hypot(flight["runMm"], flight["riseMm"])
        shape = Part.makeBox(
            length,
            flight["widthMm"],
            flight["thicknessMm"],
            App.Vector(0, 0, 0),
        )
        # The flight slopes: it is laid down flat and then pitched up about its foot.
        shape.rotate(
            App.Vector(flight["xMm"], flight["yMm"], flight["baseZMm"]),
            App.Vector(0, 1, 0),
            -flight["angleDeg"],
        )
        obj = document.addObject("Part::Feature", f"StairFlight_{flight['id']}")
        obj.Shape = shape
        obj.Label = f"Stair flight {flight['id']}"
    for landing in DESIGN["landings"]:
        shape = _box(
            landing["xMm"],
            landing["yMm"],
            landing["zMm"] - landing["thicknessMm"],
            landing["depthMm"],
            landing["widthMm"],
            landing["thicknessMm"],
        )
        obj = document.addObject("Part::Feature", f"Landing_{landing['id']}")
        obj.Shape = shape
        obj.Label = f"Landing {landing['id']}"
    for lift in DESIGN["lifts"]:
        shaft = _box(
            lift["xMm"],
            lift["yMm"],
            lift["baseZMm"],
            lift["shaftMm"],
            lift["shaftMm"],
            lift["heightMm"],
        )
        obj = document.addObject("Part::Feature", f"LiftShaft_{lift['id']}")
        obj.Shape = shaft
        obj.Label = f"Lift shaft {lift['id']}"
        car = _box(
            lift["xMm"] + 100.0,
            lift["yMm"] + 100.0,
            lift["baseZMm"],
            lift["carMm"],
            lift["carMm"],
            lift["heightMm"],
        )
        obj = document.addObject("Part::Feature", f"LiftCar_{lift['id']}")
        obj.Shape = car
        obj.Label = f"Lift car {lift['id']}"
    for run in DESIGN["runs"]:
        pipe = Part.makeCylinder(
            run["diameterMm"] / 2.0,
            run["lengthMm"],
            App.Vector(run["xMm"], run["yMm"], run["zMm"]),
        )
        obj = document.addObject("Part::Feature", f"{run['kind'].title()}_{run['id']}")
        obj.Shape = pipe
        obj.Label = f"{run['kind']} {run['id']}"
    document.recompute()

    out_dir = os.environ.get("ARCHRES_JOB_OUTDIR")
    if out_dir:
        summary = {
            "projectId": DESIGN["projectId"],
            "storeyIndex": DESIGN["storeyIndex"],
            "flights": len(DESIGN["flights"]),
            "landings": len(DESIGN["landings"]),
            "lifts": len(DESIGN["lifts"]),
            "runs": len(DESIGN["runs"]),
        }
        target = pathlib.Path(out_dir) / "commons-design.json"
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(
            json.dumps(summary, ensure_ascii=False, indent=1, sort_keys=True) + "\n",
            encoding="utf-8",
        )


build()

# --- the mesh export (W2.8): the workspace draws what the engine measured ---
import json as _json
import os as _os
import pathlib as _pathlib

_KINDS = {'Footing': 'footing', 'GradeBeam': 'grade-beam', 'Column': 'column', 'Beam': 'beam', 'Slab': 'slab'}
_PHASES = {'Footing': 'foundation', 'GradeBeam': 'foundation', 'Column': 'floor', 'Beam': 'floor', 'Slab': 'floor'}
_DEVIATION = 0.5


def _export_mesh(document, out_dir):
    objects = []
    for obj in document.Objects:
        shape = getattr(obj, "Shape", None)
        if shape is None or shape.isNull():
            continue
        points, facets = shape.tessellate(_DEVIATION)
        positions = []
        normals = []
        for facet in facets:
            if len(facet) != 3:
                continue
            p0, p1, p2 = points[facet[0]], points[facet[1]], points[facet[2]]
            ux, uy, uz = p1.x - p0.x, p1.y - p0.y, p1.z - p0.z
            vx, vy, vz = p2.x - p0.x, p2.y - p0.y, p2.z - p0.z
            nx = uy * vz - uz * vy
            ny = uz * vx - ux * vz
            nz = ux * vy - uy * vx
            length = (nx * nx + ny * ny + nz * nz) ** 0.5
            if length <= 0.0:
                continue
            nx, ny, nz = nx / length, ny / length, nz / length
            for index in facet:
                point = points[index]
                positions.extend([point.x, point.y, point.z])
                normals.extend([nx, ny, nz])
        box = shape.BoundBox
        prefix = obj.Name.split("_")[0]
        objects.append(
            {
                "id": obj.Name,
                "label": obj.Label,
                "kind": _KINDS.get(prefix, "other"),
                "phase": _PHASES.get(prefix, "other"),
                "volumeMm3": round(shape.Volume, 3),
                "bboxMinMm": [round(box.XMin, 4), round(box.YMin, 4), round(box.ZMin, 4)],
                "bboxMaxMm": [round(box.XMax, 4), round(box.YMax, 4), round(box.ZMax, 4)],
                "positions": [round(value, 4) for value in positions],
                "normals": [round(value, 6) for value in normals],
                "indices": list(range(len(positions) // 3)),
            }
        )
    payload = {"schemaVersion": '0.1.0', "units": "mm", "objects": objects}
    target = _pathlib.Path(out_dir) / 'mesh.json'
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(
        _json.dumps(payload, ensure_ascii=False, sort_keys=True) + "\n", encoding="utf-8"
    )


_export_mesh(App.ActiveDocument, _os.environ["ARCHRES_JOB_OUTDIR"])
